-- My Active Life — clean schema v2
-- DESTRUCTIVE RESET: drops app tables and old JSON payload table. Review before execution.
begin;
drop table if exists public.running_history cascade;
drop table if exists public.strength_history cascade;
drop table if exists public.sessions cascade;
drop table if exists public.daily_data cascade;
drop table if exists public.profiles cascade;
drop table if exists public.user_app_data cascade;
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,email text,timezone text not null default 'Europe/Paris',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sessions(id bigint primary key,user_id uuid not null references auth.users(id) on delete cascade,session_date date not null,day_of_week smallint not null check(day_of_week between 0 and 6),kind text not null,title text not null,planned boolean not null default true,done boolean not null default false,recorded_at timestamptz,run_category text,work_type text,duration_minutes integer,distance_km numeric(7,2),pace text,avg_hr integer,calories integer,water_temp_c numeric(4,1),note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.running_history(id bigint primary key,user_id uuid not null references auth.users(id) on delete cascade,source_session_id bigint,run_date date not null,category text,work_type text,title text not null,duration_minutes integer,distance_km numeric(7,2),pace text,avg_hr integer,calories integer,note text,created_at timestamptz not null default now());
-- source_session_id has no FK, so independent run history survives calendar deletion.
create table public.strength_history(id bigint primary key,user_id uuid not null references auth.users(id) on delete cascade,workout_date date not null,template text not null check(template in ('lowerBody','upperBody','fullBody')),title text not null,exercises jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create table public.daily_data(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,entry_date date not null,weight_kg numeric(6,2),waist_cm numeric(6,2),hips_cm numeric(6,2),sleep_hours numeric(4,2),energy smallint check(energy between 1 and 5),mood text,symptoms text[] not null default '{}',cycle_phase text,period_start boolean not null default false,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,entry_date));
create index sessions_user_date_idx on public.sessions(user_id,session_date);
create index running_history_user_date_idx on public.running_history(user_id,run_date desc);
create index strength_history_user_date_idx on public.strength_history(user_id,workout_date desc);
create index daily_data_user_date_idx on public.daily_data(user_id,entry_date desc);
do $$ declare t text; begin foreach t in array array['profiles','sessions','running_history','strength_history','daily_data'] loop
execute format('alter table public.%I enable row level security',t);
execute format('create policy %I on public.%I for select to authenticated using (auth.uid()=user_id)',t||'_select_own',t);
execute format('create policy %I on public.%I for insert to authenticated with check (auth.uid()=user_id)',t||'_insert_own',t);
execute format('create policy %I on public.%I for update to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id)',t||'_update_own',t);
execute format('create policy %I on public.%I for delete to authenticated using (auth.uid()=user_id)',t||'_delete_own',t);
execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
commit;
